INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l37',4,7,37,'The Process of Aging','衰老的过程','最高级(at its most vigorous / the likelihood is least)、have yet to do(尚未…)、though 引导让步(though imperceptible at first, …)、if + 过去分词(省略,if given the chance)、worth + 动名词(not worth mending)(NCE4 无 KS 页,考点由课文结构自取;IP:源为亚历克斯·康福特《The Process of Ageing》一篇论‘12岁身体最强健、此后活力渐衰’的科普文,无具名真实人物;通用生理事实用 100% 原创行文复述;题材=衰老生理·无害;美语化 aging/vigor;第四册第37课·U7开工)','十二岁时,人的身体最为强健。它还没长到最大、最壮,主人的智力也还没发育到极致;可正是在这个年纪,死亡的可能性降到最低。更早的时候,我们还是婴儿和幼童,要脆弱得多;再往后,我们将经历活力与抵抗力缓慢而持续的丧失——这种丧失起初难以察觉,最终却陡峭到我们再也活不下去,无论我们怎样善待自己,无论社会和医生怎样照料我们。这种随时间推移而来的活力衰退,就叫衰老,它是我们任何人所能发现的、最令人不快的事情之一。我们迟早都会明白:我们注定要这样衰退;倘若躲过战争、意外和疾病,我们终将‘老死’;而且这一过程发生的速度因人而异极小,以至于我们多半会在六十五到八十岁之间死去。少数人会死得更早,少数人会活到九十、一百岁——但概率对此不利;无论我们多么幸运、多么强健,我们能指望活多久,都有一个几乎确定的上限。人们往往会忘记这个过程,除非、也直到被提醒。多年来,许多人想当然地以为,活力的稳步流失是不言自明的,就像热水壶变凉、鞋子磨破;以为一切动物、也许还有树木之类的别的生物,按事物的本性都必然会‘磨损殆尽’。诚然,多数动物只要有机会活得够久,衰老的方式与我们大同小异;上了发条的钟表、乃至太阳本身,也确实会耗尽能量。可这些与人衰老时发生的事,并不真正类似。一只走停了的表仍是一只表,还能重新上弦;而一只又旧又磨损的表,则会变得太不可靠,终至不值得修理。然而表永远无法自我修复,因为它没有活的部件——只有金属,靠摩擦慢慢磨去。而我们,曾经能够自我修复,至少足以战胜除最猝然致命者以外的一切疾病;我们在十二岁到八十岁之间逐渐失去的,正是这种能力。','{"q":"Listen and answer — What is one of the most unpleasant discoveries we make about ourselves as we get older?","options":["That we must gradually decline and eventually die of old age","That we will live for ever","That we grow stronger with age","That age has no limit at all"],"answer_index":0}'::jsonb,'{"title":"最高级 / have yet to do / though 引导让步 / if + 过去分词(省略) / worth + 动名词","intro":"①最高级:at its most vigorous;the likelihood is least。②have yet to do,‘尚未…’。③though 引导让步,可插在两逗号之间:which, though imperceptible, …。④if + 过去分词(省略主语和 be):if given the chance。⑤worth + 动名词:not worth mending。","table":{"headers":["用法","结构","例子"],"rows":[["最高级","at its most / … est","at its most vigorous"],["have yet to do","have yet + to do","has yet to reach full strength"],["though 让步",", though + 形容词, …","though imperceptible at first"],["if + 过去分词(省略)","if + 过去分词","if given the chance"],["worth + 动名词","worth + doing","not worth mending"]]},"specialRules":[{"rule":"if/when/though 从句里,若主语与主句一致且含 be,常省略‘主语 + be’:if (it is) given the chance → if given the chance。","mark":"if given …"},{"rule":"worth 后接动名词(worth mending),不接不定式(不写 worth to mend)。","mark":"worth + doing"},{"rule":"美式拼写:aging(衰老,英式 ageing)、vigor(活力,英式 vigour)。本课已按美语写。","mark":"aging / vigor"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l37',1,NULL,'At the age of twelve, the human body is at its most vigorous. It has yet to reach its full size and strength, and its owner has yet to reach full intelligence; but at this age the likelihood of death is at its lowest. Earlier, as infants and small children, we were far more vulnerable.','十二岁时,人的身体最为强健。它还没长到最大、最壮,主人的智力也还没发育到极致;可正是在这个年纪,死亡的可能性降到最低。更早的时候,我们还是婴儿和幼童,要脆弱得多。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l37',2,NULL,'Later, we shall undergo a slow, progressive loss of vigor and resistance which, though imperceptible at first, will in the end grow so steep that we can live no longer — however well we look after ourselves, and however well society and our doctors look after us. This decline in vigor with the passing of time is called aging, and it is one of the most unwelcome discoveries any of us ever makes.','再往后,我们将经历活力与抵抗力缓慢而持续的丧失——这种丧失起初难以察觉,最终却陡峭到我们再也活不下去,无论我们怎样善待自己,无论社会和医生怎样照料我们。这种随时间推移而来的活力衰退,就叫衰老,它是我们任何人所能发现的、最令人不快的事情之一。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l37',3,NULL,'We all learn, sooner or later, that we must decline in this way; that if we escape wars, accidents, and disease we shall in the end ''die of old age''; and that this happens at a rate which varies little from person to person, so that the odds are heavy in favor of our dying between the ages of sixty-five and eighty. A few will die sooner, and a few will live on into a ninth or tenth decade — but the chances are against it, and there is a virtual limit on how long we can hope to remain alive, however lucky and robust we are.','我们迟早都会明白:我们注定要这样衰退;倘若躲过战争、意外和疾病,我们终将‘老死’;而且这一过程发生的速度因人而异极小,以至于我们多半会在六十五到八十岁之间死去。少数人会死得更早,少数人会活到九十、一百岁——但概率对此不利;无论我们多么幸运、多么强健,我们能指望活多久,都有一个几乎确定的上限。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l37',4,NULL,'People tend to forget this process unless and until they are reminded of it. For years, many assumed that the steady loss of vigor was self-evident, like the cooling of a hot kettle or the wearing-out of a pair of shoes; that all animals, and perhaps other organisms such as trees, must in the nature of things wear out. It is true that most animals age much as we do, if given the chance to live long enough, and that machines like a wound watch, or the sun itself, do run out of energy.','人们往往会忘记这个过程,除非、也直到被提醒。多年来,许多人想当然地以为,活力的稳步流失是不言自明的,就像热水壶变凉、鞋子磨破;以为一切动物、也许还有树木之类的别的生物,按事物的本性都必然会‘磨损殆尽’。诚然,多数动物只要有机会活得够久,衰老的方式与我们大同小异;上了发条的钟表、乃至太阳本身,也确实会耗尽能量。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l37',5,NULL,'But these are not really analogous to what happens when a person ages. A run-down watch is still a watch and can be rewound; an old, worn watch, by contrast, becomes so unreliable that it is finally not worth mending. Yet a watch could never repair itself, for it has no living parts — only metal, which slowly wears away by friction. We, once, could repair ourselves, well enough at least to overcome all but the most instantly fatal illnesses; and it is precisely this power that we gradually lose between the ages of twelve and eighty.','可这些与人衰老时发生的事,并不真正类似。一只走停了的表仍是一只表,还能重新上弦;而一只又旧又磨损的表,则会变得太不可靠,终至不值得修理。然而表永远无法自我修复,因为它没有活的部件——只有金属,靠摩擦慢慢磨去。而我们,曾经能够自我修复,至少足以战胜除最猝然致命者以外的一切疾病;我们在十二岁到八十岁之间逐渐失去的,正是这种能力。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
